insert into public.entries (kind, id, position, data) values
('scp', 'SCP-8041', 0, '{"id":"SCP-8041","name":"Der Seegrund-Puls","objectClass":"Euclid","clearance":"Stufe 2","acs":{"disruption":"Vlam","risk":"Caution","status":"Eingedämmt"},"warning":"Direkter Sichtkontakt mit dem Lichtpuls ist ohne Schutzbrille Klasse B untersagt.","mtf":"gamma-6","summary":"Metallischer Körper, der in regelmäßigen Abständen blaues Licht aussendet.","containment":["SCP-8041 wird in einem abgedunkelten Wasserbecken (4 × 4 × 3 m) in Sektor 9 von Site-80 gelagert.","Die Wassertemperatur ist konstant bei 6 °C zu halten. Abweichungen verkürzen das Pulsintervall.","Personal darf das Becken nur paarweise und mit Schutzbrille Klasse B betreten."],"description":["SCP-8041 ist ein glatter, ovaler Körper aus einer unbekannten Legierung, etwa 1,4 m lang.","Alle 41 Minuten sendet das Objekt einen Lichtpuls aus, der bis zu 300 m weit sichtbar ist.","Personen, die einen Puls direkt beobachten, berichten anschließend von einem Gefühl, \"gerufen\" zu werden."],"addenda":[{"kind":"recovery","title":"Bergungsprotokoll 80-041-A","meta":[["Datum","03.06.2026"],["Fundort","Waldsee, Schwarzwald"],["Einheit","Bergungsteam Süd"]],"body":["Geborgen am 03.06.2026 aus einem Waldsee im Schwarzwald durch Bergungsteam Süd.","Zivile Zeugen erhielten Amnestika Klasse A. Keine Verletzten."]},{"kind":"test","title":"Testprotokoll 80-041-T3","meta":[["Datum","14.07.2026"],["Leitung","Forschung Sektor 9"],["Ergebnis","Abgebrochen"]],"body":["Wassertemperatur auf 12 °C erhöht. Pulsintervall sank auf 19 Minuten.","Test nach [[Vorfall 80-041-Δ (Verlust einer Messsonde)]] abgebrochen."]}],"reports":["FB-80-2026-019"]}'::jsonb),
('scp', 'SCP-8007', 1, '{"id":"SCP-8007","name":"Das ungelistete Regal","objectClass":"Keter","clearance":"Stufe 3","antimemetic":true,"acs":{"disruption":"Keneq","risk":"Danger","status":"Teilweise eingedämmt","subclass":"Antimemetisch"},"warning":"Antimemetische Gefährdung. Dieses Dokument kann Ihre Erinnerung an sich selbst löschen. Notieren Sie, dass Sie es geöffnet haben.","mtf":"beta-43","summary":"Ein Archivregal, an das sich niemand erinnern kann.","containment":["Archiv 7 ist bis auf Weiteres gesperrt. Zutritt nur mit aktivem antimemetischem Filter.","Alle Erkenntnisse über SCP-8007 sind sofort schriftlich festzuhalten.","Wenn Sie diesen Absatz bereits zum zweiten Mal lesen, melden Sie sich bei der Abteilung Memetik."],"description":["SCP-8007 ist ein Stahlregal mit sieben Fächern in Archiv 7 von Site-80.","Personen, die SCP-8007 betrachten, verlieren nach etwa 40 Sekunden jede Erinnerung daran.","Der Inhalt der Fächer ist unbekannt. Drei Versuche, ihn zu dokumentieren, ergaben leere Seiten.","Auf einer dieser Seiten fand sich nachträglich der Satz: [[„Ihr habt mich gelesen. Jetzt lese ich euch.“]]."],"addenda":[{"kind":"interview","title":"Interview mit Archivarin L. Hofstetter","meta":[["Befragte","L. Hofstetter, Archiv 7"],["Vorwort","Hofstetter verließ Archiv 7 nach 6 Stunden ohne Erinnerung an den Aufenthalt."]],"body":["<Hofstetter hält ein Notizbuch in beiden Händen.>","Hofstetter: \"Ich weiß, dass ich dort war. Ich habe es aufgeschrieben.\"","Interviewer: \"Was steht in Ihren Notizen?\"","Hofstetter: \"Dass ich nicht hätte hingehen sollen.\"","<Hofstetter schlägt das Notizbuch auf. Die Seiten sind leer.>"]}],"reports":["FB-80-2026-028"]}'::jsonb),
('scp', 'SCP-8019', 2, '{"id":"SCP-8019","name":"Der stille Gast","objectClass":"Euclid","clearance":"Stufe 2","acs":{"disruption":"Vlam","risk":"Warning","status":"Eingedämmt","subclass":"Visuell"},"mtf":"eta-10","summary":"Eine Gestalt, die nur auf Kameraaufnahmen von Zelle 14-B sichtbar ist.","containment":["Zelle 14-B ist dauerhaft mit vier unabhängigen Kameras zu überwachen.","Die Stromversorgung der Zelle muss redundant ausgelegt sein."],"description":["SCP-8019 erscheint ausschließlich auf Videoaufnahmen als sitzende, menschenähnliche Gestalt.","Bei direkter Beobachtung ist die Zelle leer. Gewicht und Temperatur bleiben unverändert.","Während eines Stromausfalls stand SCP-8019 zum ersten Mal auf."],"addenda":[{"kind":"incident","title":"Vorfall 80-019-1","meta":[["Dauer","11 Sekunden"],["Ursache","Wartung der Stromversorgung"],["Bericht","FB-80-2026-011"]],"body":["Während des Ausfalls zeichnete Kamera 3 auf Notstrom weiter. SCP-8019 stand auf und wandte sich der Kamera zu.","Nach Rückkehr der Stromversorgung saß SCP-8019 wieder an seinem Platz. Die Sitzposition war um 40 cm verschoben."]}],"reports":["FB-80-2026-011"]}'::jsonb),
('scp', 'SCP-8002', 3, '{"id":"SCP-8002","name":"Kuckucksuhr ohne Zeiger","objectClass":"Safe","clearance":"Stufe 1","acs":{"disruption":"Dark","risk":"Notice","status":"Eingedämmt"},"summary":"Eine Kuckucksuhr, deren Kuckuck jeweils kurz vor einem Erdbeben ruft.","containment":["SCP-8002 hängt im Büro der Standortdirektion. Batterien sind nicht nötig."],"description":["SCP-8002 ist eine handgeschnitzte Kuckucksuhr ohne Zeiger, vermutlich aus dem 19. Jahrhundert.","Der Kuckuck ruft zwischen 30 und 90 Sekunden vor einem Erdbeben der Stärke 3 oder höher, weltweit."],"addenda":[{"kind":"note","title":"Notiz der Standortdirektorin","body":["Sie ist laut. Sie ist zuverlässig. Sie bleibt."],"sign":"Standortdirektion Site-80"}]}'::jsonb),
('scp', 'SCP-8066', 4, '{"id":"SCP-8066","name":"[ZUGRIFF BESCHRÄNKT]","objectClass":"Keter","clearance":"Stufe 4","locked":{"required":"Stufe 4","realName":"Der Totenfunk"},"acs":{"secondary":"Nachrichtlich","disruption":"Ekhi","risk":"Critical","status":"Nicht eindämmbar"},"warning":"Die in diesem Dokument genannte Zahlenfolge ist nicht auszuwerten. Zuwiderhandlung wird als Selbstgefährdung gewertet.","mtf":"gamma-5","summary":"Ein Funkturm, der ein Signal sendet, das nur Verstorbene empfangen.","containment":["Das Gelände um SCP-8066 ist als Sperrgebiet \"Funkstation 80-Nord\" ausgewiesen.","Empfangsgeräte im Umkreis von 2 km sind auf Frequenz 66,6 MHz zu sperren."],"description":["SCP-8066 ist ein stillgelegter Sendemast aus den 1950er Jahren ohne Stromanschluss.","Er sendet dennoch dauerhaft ein schwaches Signal mit einer sich wiederholenden Zahlenfolge.","Die Folge entspricht den Sterbedaten von Personen, die im Umkreis gelebt haben, Tage bevor diese eintreten."],"addenda":[{"kind":"note","title":"Notiz der Standortdirektion","sign":"Standortdirektion Site-80","body":["Die Liste wird nicht mehr ausgewertet. Wer sie liest, findet irgendwann einen bekannten Namen."]}]}'::jsonb),
('scp', 'SCP-8000', 5, '{"id":"SCP-8000","name":"[DATEN GELÖSCHT]","objectClass":"Esoteric","clearance":"Stufe 5","locked":{"required":"Stufe 5","corrupt":true,"realName":"Raum Null"},"acs":{"containment":"Esoteric","secondary":"Thaumiel","disruption":"Amida","risk":"Danger","status":"Fundament","subclass":"Strukturell"},"warning":"Freigabe Stufe 5 erforderlich. Jeder Abruf wird dem Administrator persönlich gemeldet.","mtf":"alpha-1","summary":"Das Fundament von Site-80.","containment":["SCP-8000 kann und soll nicht eingedämmt werden. Site-80 wurde um das Objekt herum gebaut."],"description":["SCP-8000 ist ein Raum unter dem tiefsten Geschoss von Site-80, der in keinem Bauplan verzeichnet ist.","Solange der Raum unbetreten bleibt, bleiben alle Eindämmungen am Standort stabil.","Der Administrator ist die einzige bekannte Person, die ihn betreten hat."],"addenda":[{"kind":"note","title":"Vermerk des Administrators","body":["Manche Türen sichern wir nicht, um etwas drinnen zu halten. Sondern damit niemand vergisst, warum es sie gibt."],"sign":"Der Administrator"}]}'::jsonb),
('personnel', 'P-80-0001', 0, '{"id":"P-80-0001","name":"Dr. Ilse Brandt","photo":"ilse_brandt","role":"Standortdirektorin","department":"Standortleitung","clearance":"Stufe 4","status":"Aktiv","since":"2009","quote":"Vertrauen ist ein Eindämmungsfehler, der noch nicht passiert ist.","summary":"Leitet Site-80 seit der Neustrukturierung von 2014. Verantwortlich für sämtliche Eindämmungs- und Forschungsprotokolle am Standort.","notes":["Hat die Zusammenarbeit mit [[der Global Occult Coalition]] im Jahr 2019 persönlich beendet.","Zugriff auf O5-Korrespondenz über gesicherten Kanal."],"timeline":[{"year":"2009","text":"Eintritt als Forscherin, Site-[[19]]."},{"year":"2012","text":"Beförderung zur Abteilungsleiterin Eindämmungstechnik."},{"year":"2014","text":"Ernennung zur Standortdirektorin von Site-80."},{"year":"2019","text":"Leitung der internen Untersuchung [[zum Verschwinden von Seite 4, Akte 80-117]]."}],"psych":{"access":"denied","required":"Stufe 4","verdict":{"label":"Einsatzfähig","tone":"ok"},"date":"2026-08-30","metrics":[{"label":"Belastbarkeit","value":96},{"label":"Kooperation","value":61},{"label":"Kognitive Integrität","value":93}],"text":["Außergewöhnlich kontrolliert. Trifft Entscheidungen ohne erkennbares Zögern.","Vertraut niemandem vollständig, am wenigsten sich selbst.","Führt ein privates Tagebuch, dessen Existenz sie bestreitet."]},"incidents":["Keine disziplinarischen Vermerke."]}'::jsonb),
('personnel', 'P-80-0117', 1, '{"id":"P-80-0117","name":"Dr. Duncan Maynard","photo":"duncan_maynard","role":"Leitender Forscher","department":"Anomalienforschung / RAISA-Verbindung","clearance":"RAISA","status":"Aktiv","since":"2016","quote":"Jede Akte erzählt eine Geschichte. Meistens die falsche.","summary":"Verbindungsoffizier zwischen der Forschungsabteilung und RAISA. Verwaltet die Aktenführung zu Feldeinsätzen in Mitteleuropa.","notes":["Letzte Anmeldung von ungewöhnlichem Endpunkt. Sicherheitsprüfung angeordnet.","Ausbildung: Promotion in Informationswissenschaft, [[Universität Heidelberg]]."],"timeline":[{"year":"2016","text":"Rekrutierung nach Kontakt mit einem anomalen Dokument."},{"year":"2018","text":"Versetzung zu RAISA, Außenstelle Site-80."},{"year":"2023","text":"Leitender Forscher. Verantwortlich für Feldakten Mitteleuropa."},{"year":"2026","text":"Sicherheitsprüfung wegen auffälliger Anmeldung eingeleitet."}],"psych":{"access":"granted","verdict":{"label":"Einsatzfähig","tone":"ok"},"date":"2026-04-11","metrics":[{"label":"Belastbarkeit","value":78},{"label":"Kooperation","value":64},{"label":"Kognitive Integrität","value":91}],"text":["Ruhig, methodisch, neigt zu übermäßiger Dokumentation.","Zeigt geringe Toleranz gegenüber unvollständigen Akten.","Empfehlung: keine Einschränkungen. [[Nachtrag RAISA: Kontakte zur UIU sind unverzüglich zu melden]]."]},"incidents":["2021: Verspätete Abgabe eines Berichts. Ermahnung."]}'::jsonb),
('personnel', 'P-80-0342', 2, '{"id":"P-80-0342","name":"Agentin Mara Kessler","role":"Einsatzleiterin","department":"Sicherheitsdienst / Feldeinsätze","clearance":"Stufe 3","status":"Aktiv","since":"2018","quote":"Rein, raus, keiner merkt was.","summary":"Leitet die Bergungsteams im süddeutschen Raum. Über 40 erfolgreiche Bergungen ohne zivile Zwischenfälle.","notes":["Ausgezeichnet nach Vorfall [[80-17, Eindämmungsbruch in Sektor 9]]."],"timeline":[{"year":"2014","text":"Dienst bei der Bundespolizei, GSG [[9]]."},{"year":"2018","text":"Rekrutierung durch die Foundation."},{"year":"2021","text":"Einsatzleiterin der Bergungsteams Süd."},{"year":"2026","text":"Bergung im Schwarzwald (FB-80-2026-019)."}],"psych":{"access":"granted","verdict":{"label":"Einsatzfähig","tone":"ok"},"date":"2026-02-02","metrics":[{"label":"Belastbarkeit","value":94},{"label":"Kooperation","value":58},{"label":"Kognitive Integrität","value":88}],"text":["Hohe Stressresistenz. Entscheidet schnell und konsequent.","Tendenz, Risiken für das eigene Team zu unterschätzen."]},"incidents":["2022: Eigenmächtiger Zugriff ohne Freigabe. Erfolgreich, aber gerügt."]}'::jsonb),
('personnel', 'P-80-0588', 3, '{"id":"P-80-0588","name":"Dr. Tomas Reyes","role":"Forscher","department":"Memetik und Kognitionsgefahren","clearance":"Stufe 3","status":"Beurlaubt","since":"2020","quote":"Man kann nicht vergessen, was man nie gesehen hat. Oder?","summary":"Spezialist für antimemetische Filter. Derzeit beurlaubt bis zum Abschluss einer kognitiven Beurteilung.","notes":["Beurlaubung angeordnet nach Feldbericht FB-80-2026-028.","Wiedereingliederung geplant: [[03.11.2026]]."],"timeline":[{"year":"2020","text":"Eintritt in die Abteilung Memetik."},{"year":"2024","text":"Entwicklung eines tragbaren antimemetischen Filters."},{"year":"2026","text":"Untersuchung von Archiv 7. Danach beurlaubt."}],"psych":{"access":"granted","verdict":{"label":"Eingeschränkt","tone":"bad"},"date":"2026-09-20","metrics":[{"label":"Belastbarkeit","value":41},{"label":"Kooperation","value":72},{"label":"Kognitive Integrität","value":23}],"text":["Seit Archiv 7: wiederholte Fragen nach Personen, die nicht existieren.","Schreibt Notizen an sich selbst, die er später nicht erkennt.","Beurteilung: [[antimemetische Kontamination durch SCP-8007, Rückkehr in den Dienst nicht empfohlen]]."]},"incidents":["2026: Unerlaubtes Mitnehmen eines Filterprototyps nach Hause."]}'::jsonb),
('personnel', 'P-80-1024', 4, '{"id":"P-80-1024","name":"Lena Hofstetter","role":"Archivarin","department":"Archiv und Dokumentation","clearance":"Stufe 2","status":"Aktiv","since":"2022","quote":"Wenn es nicht im Verzeichnis steht, existiert es nicht. Hoffentlich.","summary":"Pflegt die physischen Archive von Site-80 und digitalisiert ältere Fallakten.","notes":["Meldete wiederholt fehlende Seiten in Archivbestand 7."],"timeline":[{"year":"2022","text":"Eintritt als Archivassistentin."},{"year":"2024","text":"Leitung der Digitalisierung der Altakten."},{"year":"2026","text":"Meldung zu Archiv 7 (FB-80-2026-028)."}],"psych":{"access":"granted","verdict":{"label":"Einsatzfähig","tone":"ok"},"date":"2026-01-15","metrics":[{"label":"Belastbarkeit","value":70},{"label":"Kooperation","value":86},{"label":"Kognitive Integrität","value":82}],"text":["Gewissenhaft und neugierig. Neugier wurde als Risiko vermerkt."]},"incidents":["Keine disziplinarischen Vermerke."]}'::jsonb),
('personnel', 'P-80-0731', 5, '{"id":"P-80-0731","name":"Dr. Timothy Quebec Jr.","photo":"timothy_quebec_jr","role":"Wissenschaftler, Xenobiologie","department":"Forschung und Entwicklung","clearance":"Stufe 3","status":"Aktiv","since":"2021","quote":"In Lagos habe ich Schlimmeres gesehen als SCP-8041. Den Verkehr, zum Beispiel.","summary":"Stammt aus Lagos, Nigeria. Promovierte in Kapstadt über Anomalien in Mikroorganismen. Gilt als humorvollster Mitarbeiter von Site-80, nach eigener Aussage auch als bestaussehender.","notes":["Hat dreimal beantragt, die Kaffeemaschine als SCP einzustufen.","Andauernder Konflikt mit Archivarin L. Hofstetter wegen \"eines ausgeliehenen Kugelschreibers\" (2023)."],"timeline":[{"year":"2021","text":"Eintritt in die Forschungsabteilung von Site-80."},{"year":"2023","text":"Der Kugelschreiber-Vorfall. Beide Parteien verweigern eine Aussage."},{"year":"2025","text":"Leitung der Probenanalyse zu SCP-8041."}],"psych":{"access":"granted","verdict":{"label":"Einsatzfähig","tone":"ok"},"date":"2026-06-02","metrics":[{"label":"Belastbarkeit","value":88},{"label":"Kooperation","value":79},{"label":"Humor","value":99}],"text":["Nutzt Humor zur Stressbewältigung. Wirksam.","Erwähnte Archivarin Hofstetter in 11 von 12 Sitzungen ungefragt."]},"incidents":["2024: Verwarnung wegen eines Furzkissens im Besprechungsraum der Standortdirektion."]}'::jsonb),
('personnel', 'P-80-0912', 6, '{"id":"P-80-0912","name":"Halvard Hallström","photo":"halvard_hallstroem","role":"Operator, MTF Delta-5","department":"Mobile Task Forces","clearance":"Stufe 2","status":"Beobachtung","since":"2023","quote":"Sag mir, was zu tun ist. Nicht, warum es mein Schicksal ist.","summary":"Aus Kiruna. War über zehn Jahre Söldner der [[Valravn Corporation]] und glaubte lange an deren Mischung aus nordischem Schicksalsglauben und Profitdenken. Als seine Einheit bei einem Einsatz gegen [[Las Víboras]] als Köder geopfert wurde, setzte er sich ab und wurde von der Stiftung unter strenger Aufsicht in MTF Delta-5 aufgenommen.","notes":["Schweigsam. Prüft Befehle doppelt, bevor er sie ausführt.","Reagiert allergisch auf Reden von „Pflicht“ und „Bestimmung“.","Kollegen schätzen sein Können, vertrauen ihm aber nur zögerlich."],"timeline":[{"year":"2011","text":"Anwerbung durch die Valravn Corporation, Kiruna."},{"year":"2022","text":"Einsatz gegen Las Víboras. Seine Einheit wird [[als Köder geopfert]]; einziger Überlebender."},{"year":"2023","text":"Setzt sich ab und stellt sich der Stiftung. Aufnahme in MTF Delta-5 unter Auflagen."}],"psych":{"access":"denied","required":"Stufe 3","verdict":{"label":"Unter Beobachtung","tone":"warn"},"date":"2026-09-02","metrics":[{"label":"Belastbarkeit","value":88},{"label":"Kooperation","value":41},{"label":"Loyalität","value":52}],"text":["Hohe Einsatzfähigkeit, kaum Stressreaktionen im Feld.","Tiefes Misstrauen gegenüber Autorität, besonders bei ideologisch begründeten Befehlen.","Spricht nicht über seine alte Einheit. Trägt [[ihre Erkennungsmarken]] bei sich."]},"incidents":["Verweigerte 2025 einen Befehl bis zur schriftlichen Bestätigung. Kein Verstoß festgestellt."]}'::jsonb),
('personnel', 'X-80-0003', 7, '{"id":"X-80-0003","name":"Corvus Finch","photo":"corvus_finch","role":"Externe Person von Interesse","department":"FBI / Unusual Incidents Unit","clearance":"Keine","status":"Beobachtung","since":"2026","summary":"Special Agent der UIU. Zeigt anhaltendes Interesse an Foundation-Aktivitäten im Zuständigkeitsbereich von Site-80.","notes":["Überwachung durch RAISA angeordnet.","Kontaktaufnahme nur mit Genehmigung der Standortdirektion."],"timeline":[{"year":"2019","text":"Versetzung zur Unusual Incidents Unit."},{"year":"2025","text":"Erstmals in Foundation-Berichten erwähnt."},{"year":"2026","text":"Eröffnung der Fallakte \"DIE FOUNDATION\" durch die UIU."}],"psych":{"access":"granted","verdict":{"label":"Risiko","tone":"warn"},"date":"2026-10-01","metrics":[{"label":"Hartnäckigkeit","value":97},{"label":"Kooperation","value":12},{"label":"Bedrohungsgrad","value":74}],"text":["RAISA-Einschätzung: hartnäckig, einfallsreich, schwer abzuschrecken.","Wahrscheinlichkeit eines Zugriffsversuchs auf SCiPnet: hoch."]},"incidents":["Keine Foundation-Vermerke."]}'::jsonb),
('report', 'FB-80-2026-033', 0, '{"id":"FB-80-2026-033","title":"Valravn-Spuren bei Kiruna","date":"2026-10-18","author":"P-80-0912","location":"Waldgebiet südlich von [[Kiruna]], Schweden","classification":"Geheim","status":"Offen","summary":"Delta-5 findet ein verlassenes Lager der Valravn Corporation. Hallström erkennt die Handschrift seiner alten Einheit.","situation":["Satellitenbilder zeigten ein getarntes Lager in einem Waldgebiet bei Kiruna. Delta-5 wurde zur Aufklärung entsandt, Operator Hallström als Ortskundiger."],"timeline":[{"time":"02:10","text":"Trupp erreicht das Gebiet zu Fuß. Keine Bewegung, keine Wärmesignaturen."},{"time":"02:45","text":"Lager gefunden: Zelte, Feuerstellen, ein Funkmast. Seit etwa zwei Wochen verlassen."},{"time":"03:05","text":"An einem Baum ein eingeritztes Rabenzeichen. Hallström identifiziert es als Markierung seiner [[ehemaligen Einheit]]."},{"time":"03:30","text":"Im Funkzelt Unterlagen zu [[Site-80 und eine Liste mit Namen von Delta-5]] sichergestellt."}],"measures":["Unterlagen an RAISA übergeben.","Hallström bis zur Auswertung von weiteren Einsätzen in Skandinavien abgezogen."],"assessment":["Die Valravn Corporation beobachtet Delta-5, möglicherweise gezielt Hallström. Er hat den Fund selbst gemeldet und alles korrekt dokumentiert.","Empfehlung: Aufsicht beibehalten, aber Vertrauen nicht weiter entziehen."],"images":[{"src":"addendum.svg","caption":"Hallström und Truppführer am Lager, Nachtaufnahme"}],"involved":["P-80-0912"]}'::jsonb),
('report', 'FB-80-2026-031', 1, '{"id":"FB-80-2026-031","title":"Externe Aufklärungsaktivität","date":"2026-10-22","author":"P-80-0001","location":"Site-80, Netzwerkgrenze","classification":"Streng geheim","status":"Offen","summary":"Hinweise auf verdeckte Aufklärung durch eine staatliche Stelle.","situation":["Seit Anfang Oktober registriert die Netzwerküberwachung vereinzelte Verbindungsversuche von außerhalb der Foundation-Infrastruktur."],"timeline":[{"time":"23:58","text":"Schwaches Signal an der Netzwerkgrenze registriert. Ursprung nicht eindeutig bestimmbar."},{"time":"00:04","text":"Signal bricht ab. Muster ähnelt früheren Vorfällen."},{"time":"07:30","text":"Auswertung durch RAISA: Mehrere Indizien deuten auf die [[Unusual Incidents Unit des FBI]]."}],"measures":["RAISA informiert und Überwachung der Netzwerkgrenze verdoppelt.","Anmeldungen von Forschungspersonal werden zusätzlich protokolliert."],"assessment":["Gezielte Aufklärung durch eine externe Stelle ist wahrscheinlich. Empfehlung: erhöhte Wachsamkeit bei Anmeldungen von Forschungspersonal."],"images":[{"caption":"Signalverlauf an der Netzwerkgrenze, 23:58 Uhr"}],"involved":["P-80-0001","X-80-0003"]}'::jsonb),
('report', 'FB-80-2026-028', 2, '{"id":"FB-80-2026-028","title":"Gedächtnislücken im Archivpersonal","date":"2026-09-14","author":"P-80-1024","location":"Site-80, Archiv 7","classification":"Geheim","status":"Offen","summary":"Drei Mitarbeiter können sich nicht an den Inhalt eines bestimmten Regals erinnern.","situation":["Archivbestand 7 enthält ein Regal, das in keinem Verzeichnis geführt wird."],"timeline":[{"time":"09:15","text":"Archivarin Hofstetter meldet ein Regal ohne Verzeichniseintrag."},{"time":"09:40","text":"Drei Mitarbeiter betrachten das Regal und verlieren nach etwa 40 Sekunden jede Erinnerung daran."},{"time":"14:00","text":"Dr. Reyes untersucht das Regal mit antimemetischem Filter. Ergebnis: [[sieben Fächer, in jedem eine Personalakte von Site-80, darunter seine eigene]]."}],"measures":["Archiv 7 bis auf Weiteres gesperrt.","Zutritt nur mit Filter und zweiter Begleitperson."],"assessment":["Antimemetische Eigenschaft bestätigt. Weitere Untersuchung erforderlich."],"images":[{"caption":"Archiv 7, Regal ohne Verzeichniseintrag"},{"caption":"Filteraufnahme, Dr. Reyes"}],"involved":["P-80-1024","P-80-0588"]}'::jsonb),
('report', 'FB-80-2026-019', 3, '{"id":"FB-80-2026-019","title":"Lichtphänomene im Schwarzwald","date":"2026-06-03","author":"P-80-0342","location":"Schwarzwald, nahe [[Triberg]]","classification":"Vertraulich","status":"Abgeschlossen","summary":"Wiederkehrende Lichter über einem Waldsee. Ursache geborgen und eingedämmt.","situation":["Anwohner meldeten über drei Wochen hinweg blaue Lichter über einem Waldsee."],"timeline":[{"time":"21:00","text":"Einsatzteam erreicht den See. Lichter in regelmäßigen Abständen sichtbar."},{"time":"23:40","text":"Bergungsteam findet am Seegrund ein metallisches Objekt mit gleichmäßigem Puls."},{"time":"03:10","text":"Objekt geborgen und nach Site-80 überführt."}],"measures":["Zivile Zeugen erhielten Amnestika Klasse A.","Deckgeschichte: Untersuchung von Methangas am Seeufer."],"assessment":["Objekt eingedämmt als SCP-8041. Fall abgeschlossen."],"images":[{"caption":"Waldsee bei Nacht, Lichter über der Wasseroberfläche"},{"caption":"Bergung des Objekts"}],"involved":["P-80-0342"]}'::jsonb),
('report', 'FB-80-2026-011', 4, '{"id":"FB-80-2026-011","title":"Zwischenfall in Eindämmungszelle 14-B","date":"2026-03-21","author":"P-80-0117","location":"Site-80, Sektor 14","classification":"Geheim","status":"Abgeschlossen","summary":"Kurzzeitiger Ausfall der Eindämmung während Routinewartung.","situation":["Routinewartung der Stromversorgung in Sektor 14."],"timeline":[{"time":"10:12","text":"Stromversorgung von Zelle 14-B fällt für 11 Sekunden aus."},{"time":"10:13","text":"Notstrom greift. Das Objekt zeigt keine Aktivität."},{"time":"11:30","text":"Auswertung der Aufzeichnung zeigt jedoch [[eine zweite Gestalt in Zelle 14-B, die vor dem Ausfall nicht da war]]."}],"measures":["Wartungsprotokolle angepasst.","Wartung nur noch mit zweitem, unabhängigem Stromkreis."],"assessment":["Keine Verletzten. Ursache des Aufzeichnungsinhalts ungeklärt."],"images":[{"caption":"Kamera 3, Zelle 14-B, 10:12 Uhr"}],"involved":["P-80-0117"]}'::jsonb),
